 void DrawRelicBag(Rect r){var a=Adventure;if(!a)return;Text(new Rect(r.x+62,r.y+338,r.width-124,33),AdventureProgress.T("유물 · 정수 ","Relics · Essence ","遺物 · 精髄 ")+a.State.essence,new GUIStyle(dark){fontSize=18});for(int i=0;i<3;i++){float y=r.y+382+i*74;bool own=a.Relics.Owns(i);Text(new Rect(r.x+62,y,240,29),own?AdventureRelics.Name(i)+" +"+a.Relics.Rank(i):AdventureProgress.T("미발견 유물","Undiscovered relic","未発見の遺物"),new GUIStyle(dark){fontSize=14});Text(new Rect(r.x+62,y+29,215,38),own?a.Relics.EffectDescription(i):AdventureProgress.T("보스·후속 의뢰로 획득","Earn from boss / follow-up quests","ボス・続きの依頼で獲得"),new GUIStyle(dark){fontSize=11});GUI.enabled=own;if(Button(new Rect(r.x+287,y+4,94,39),a.Relics.State.equipped==i?AdventureProgress.T("해제","Off","外す"):AdventureProgress.T("장착","Equip","装備"),true))a.Relics.Equip(a.Relics.State.equipped==i?-1:i);GUI.enabled=own&&a.CanManage&&a.Relics.Rank(i)<3&&a.State.essence>=a.Relics.UpgradeCost(i);if(Button(new Rect(r.x+387,y+4,131,39),a.Relics.Rank(i)>=3?"MAX":AdventureProgress.T("강화 ","Upgrade ","強化 ")+a.Relics.UpgradeCost(i),true))a.Relics.Upgrade(i);GUI.enabled=true;}}
